841	// assertCreateOutcome 断言“创建成功”这一独立结果，与列表刷新结果互不混淆：
842	// 成功提示含本次编号、表单恢复初始填写状态、按钮恢复可用、服务端确已保存。
843	// 必须在第二次查询放行之后调用（按钮在刷新这一步落定后才恢复）。
844	async function assertCreateOutcome(page, baseURL, created) {
845	  await waitForMessageKind(page, 'ok');
846	  const msg = await readMessage(page);
847	  assert.ok(msg.className.includes('ok'), `应保留创建成功提示，实际 class: ${msg.className}`);
848	  assert.ok(msg.text.startsWith(SUCCESS_PREFIX), `应保留创建成功提示，实际: ${msg.text}`);
849	  assert.equal(
850	    msg.text.slice(SUCCESS_PREFIX.length),
851	    created.id,
852	    '成功提示中的编号应与创建结果一致',
853	  );
854	  assert.deepEqual(await readFormState(page), {
855	    name: '',
856	    game: '',
857	    capacity: '',
858	    capacityDisabled: true,
859	    turnSeconds: '',
860	    submitDisabled: false,
861	  }, '创建成功后表单应复位、创建按钮应恢复可用');
862	  const saved = (await readServerRooms(baseURL)).find((r) => r.id === created.id);
863	  assert.ok(saved, '服务端应已保存本次创建的房间');
864	  return { msgText: msg.text, saved };
865	}
