867	// assertRoomRowCells 逐列断言一个房间行沿用现有显示含义，且编号/配置/时间
868	// 与创建结果（或查询返回的该房间记录）一致。
869	function assertRoomRowCells(row, room, expected) {
870	  assert.equal(row.cells[0], room.id, '房间编号应与创建结果一致');
871	  assert.equal(row.cells[1], room.name, '名称应与创建结果一致');
