// 缺项被拦截后，补齐“此时”的规则与人数即可正常创建——验证保留的表单
// 与联动状态衔接正确，而不是带着残留值提交。
test('缺人数被拦截后，按当前规则补齐人数可正常创建并正确复位', { timeout: 60000 }, async (t) => {
  const { page, baseURL } = await setupPage(t);
