// 切换规则后等待人数下拉完成重建：禁用态与给定期望值一致。
async function waitForCapacityValue(page, value) {
  await page.waitForFunction(
    (want) => {
      const sel = document.getElementById('capacity');
      return want === null ? sel.disabled : (!sel.disabled && sel.value === want);
    },
    { timeout: 5000 },
    value,
  );
}

